/* ============================================
   LILAMA2 CHATBOT - Floating Widget Styles
   ============================================ */

:root {
  --primary: #005baa;
  --primary-dark: #003d77;
  --primary-light: #e8f1fa;
  --accent: #f5a623;
  --success: #27ae60;
  --surface: #ffffff;
  --bg: #f0f4f9;
  --text: #1a1a2e;
  --text-muted: #6b7c93;
  --border: #e2e8f0;
  --shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
  --radius: 12px;
  --radius-sm: 8px;
  --font: 'Segoe UI', Arial, Helvetica, sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
}

button, input { font: inherit; }
button { cursor: pointer; }

/* ============ FLOATING ACTION BUTTON ============ */
.chat-fab {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 99999;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  border: none;
  background: linear-gradient(135deg, var(--primary), var(--primary-dark));
  color: #fff;
  box-shadow: 0 6px 20px rgba(0, 91, 170, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  animation: fabEntrance 0.6s ease-out;
}

@keyframes fabEntrance {
  from { opacity: 0; transform: scale(0); }
  60%  { transform: scale(1.15); }
  to   { opacity: 1; transform: scale(1); }
}

.chat-fab:hover {
  transform: scale(1.08);
  box-shadow: 0 8px 28px rgba(0, 91, 170, 0.45);
}

.chat-fab:active {
  transform: scale(0.95);
}

.fab-icon {
  position: absolute;
  width: 28px;
  height: 28px;
  transition: opacity 0.3s, transform 0.3s;
}

.fab-icon-chat { opacity: 1; transform: rotate(0); }
.fab-icon-close { opacity: 0; transform: rotate(-90deg); }

.chat-fab.is-open .fab-icon-chat { opacity: 0; transform: rotate(90deg); }
.chat-fab.is-open .fab-icon-close { opacity: 1; transform: rotate(0); }

.fab-badge {
  position: absolute;
  top: -2px;
  right: -2px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #e74c3c;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--surface);
  display: none;
}

.fab-badge.show { display: flex; }

/* ============ CHAT WIDGET ============ */
.chat-widget {
  position: fixed;
  bottom: 100px;
  right: 24px;
  z-index: 99998;
  width: 380px;
  height: 600px;
  max-height: calc(100dvh - 130px);
  background: var(--surface);
  border-radius: 16px;
  box-shadow: 0 16px 60px rgba(0, 0, 0, 0.18);
  border: 1px solid var(--border);
  display: none;
  overflow: hidden;
  animation: widgetIn 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  transform-origin: bottom right;
}

@keyframes widgetIn {
  from { opacity: 0; transform: scale(0.85) translateY(20px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

.chat-widget.is-open {
  display: flex;
  flex-direction: column;
}

.chat-widget-inner {
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* --- HEADER --- */
.cw-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 18px;
  background: linear-gradient(135deg, var(--primary), var(--primary-dark));
  color: #fff;
  flex-shrink: 0;
}

.cw-header-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.cw-avatar {
  flex-shrink: 0;
}

.cw-avatar img {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid rgba(255, 255, 255, 0.4);
  background: #fff;
}

.cw-header-info {
  min-width: 0;
}

.cw-header-info h2 {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cw-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  opacity: 0.9;
  margin-top: 2px;
}

.cw-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--success);
  display: inline-block;
  animation: pulseDot 2s infinite;
}

@keyframes pulseDot {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.cw-close-btn {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
  font-size: 22px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
}

.cw-close-btn:hover {
  background: rgba(255, 255, 255, 0.3);
}

/* --- QUICK ACTIONS --- */
.cw-quick {
  display: flex;
  gap: 6px;
  padding: 10px 14px;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
  flex-shrink: 0;
  scrollbar-width: none;
}

.cw-quick::-webkit-scrollbar { display: none; }

.cw-quick button {
  flex-shrink: 0;
  min-height: 32px;
  padding: 5px 12px;
  border: 1px solid var(--border);
  border-radius: 20px;
  font-size: 13px;
  color: var(--primary);
  background: var(--surface);
  white-space: nowrap;
  transition: all 0.2s;
}

.cw-quick button:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

/* --- MESSAGES --- */
.cw-messages {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  scroll-behavior: smooth;
  background: var(--bg);
}

.cw-messages > :first-child {
  margin-top: auto;
}

/* message row */
.msg-row {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  animation: msgIn 0.3s ease-out;
}

@keyframes msgIn {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

.msg-row.bot { justify-content: flex-start; }
.msg-row.user { justify-content: flex-end; }

.msg-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
  margin-bottom: 2px;
}

.msg-bubble {
  max-width: 85%;
  padding: 10px 14px;
  border-radius: 16px;
  font-size: 14px;
  line-height: 1.5;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  position: relative;
}

.msg-row.bot .msg-bubble {
  background: var(--surface);
  border: 1px solid var(--border);
  border-bottom-left-radius: 4px;
  color: var(--text);
}

.msg-row.user .msg-bubble {
  background: linear-gradient(135deg, var(--primary), var(--primary-dark));
  color: #fff;
  border-bottom-right-radius: 4px;
}

.msg-time {
  font-size: 10px;
  color: var(--text-muted);
  margin-top: 4px;
  padding-left: 2px;
}

.msg-row.user .msg-time {
  text-align: right;
  color: rgba(255, 255, 255, 0.6);
}

/* --- TYPING INDICATOR --- */
.cw-typing {
  display: none;
  align-items: center;
  gap: 4px;
  padding: 8px 16px;
  background: var(--bg);
  border-top: 1px solid var(--border);
}

.cw-typing.show { display: flex; }

.cw-typing span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--primary);
  animation: typingDot 1.4s infinite ease-in-out;
}

.cw-typing span:nth-child(2) { animation-delay: 0.2s; }
.cw-typing span:nth-child(3) { animation-delay: 0.4s; }

@keyframes typingDot {
  0%, 80%, 100% { transform: scale(0.6); opacity: 0.3; }
  40% { transform: scale(1); opacity: 1; }
}

/* --- COMPOSER --- */
.cw-composer {
  display: flex;
  gap: 8px;
  padding: 10px 14px 12px;
  border-top: 1px solid var(--border);
  background: var(--surface);
  flex-shrink: 0;
}

.cw-composer input {
  flex: 1;
  min-height: 42px;
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 0 16px;
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
  background: var(--bg);
}

.cw-composer input:focus {
  border-color: var(--primary);
  background: var(--surface);
}

.cw-voice-btn,
.cw-send-btn {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}

.cw-voice-btn {
  background: var(--bg);
  color: var(--text-muted);
  border: 1px solid var(--border);
}

.cw-voice-btn:hover { color: var(--primary); border-color: var(--primary); }

.cw-send-btn {
  background: linear-gradient(135deg, var(--primary), var(--primary-dark));
  color: #fff;
}

.cw-send-btn:hover { opacity: 0.9; }
.cw-send-btn svg,
.cw-voice-btn svg {
  width: 20px;
  height: 20px;
}

/* --- FOOTER --- */
.cw-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 14px;
  font-size: 11px;
  color: var(--text-muted);
  background: var(--bg);
  border-top: 1px solid var(--border);
  flex-shrink: 0;
}

.cw-footer a {
  color: var(--primary);
  text-decoration: none;
  font-weight: 600;
}

.cw-footer a:hover { text-decoration: underline; }

.cw-footer-sep { opacity: 0.4; }

/* ============ THANH CUỘN ============ */
.cw-messages::-webkit-scrollbar { width: 4px; }
.cw-messages::-webkit-scrollbar-track { background: transparent; }
.cw-messages::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 2px; }

/* ============ RESPONSIVE ============ */
@media (max-width: 480px) {
  .chat-fab {
    bottom: 16px;
    right: 16px;
    width: 54px;
    height: 54px;
  }

  .fab-icon { width: 24px; height: 24px; }

  .chat-widget {
    bottom: 0;
    right: 0;
    left: 0;
    top: 0;
    width: 100%;
    height: 100dvh;
    max-height: 100dvh;
    border-radius: 0;
    border: none;
  }

  .cw-header {
    padding: 14px 14px;
    padding-top: calc(14px + env(safe-area-inset-top));
  }

  .cw-messages { padding: 12px; }

  .msg-bubble {
    max-width: 90%;
    font-size: 15px;
  }

  .cw-composer {
    padding: 8px 12px calc(8px + env(safe-area-inset-bottom));
  }

  .cw-quick {
    padding: 8px 12px;
  }

  .cw-footer {
    padding-bottom: calc(8px + env(safe-area-inset-bottom));
  }
}

(function () {
  "use strict";

  /* ---- DOM refs ---- */
  var toggleBtn  = document.getElementById("chatToggle");
  var widget     = document.getElementById("chatWidget");
  var closeBtn   = document.getElementById("chatClose");
  var messagesEl = document.getElementById("messages");
  var form       = document.getElementById("chatForm");
  var input      = document.getElementById("messageInput");
  var voiceBtn   = document.getElementById("voiceButton");
  var typingEl   = document.getElementById("typingIndicator");
  var badge      = toggleBtn.querySelector(".fab-badge");

  var chatContext    = {};
  var chatSessionId  = getChatSessionId();
  var SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  var recognition    = null;
  var isListening    = false;
  var hasShownVoiceFallback = false;
  var isOpen         = false;

  /* ---- helpers ---- */

  function getChatSessionId() {
    var key = "admissions-chat-session-id";
    try {
      var existing = window.localStorage.getItem(key);
      if (existing) return existing;
      var value = window.crypto && window.crypto.randomUUID
        ? window.crypto.randomUUID()
        : "web-" + Date.now() + "-" + Math.random().toString(16).slice(2);
      window.localStorage.setItem(key, value);
      return value;
    } catch (e) {
      return "web-" + Date.now() + "-" + Math.random().toString(16).slice(2);
    }
  }

  /* ---- open / close ---- */

  function openChat() {
    isOpen = true;
    widget.classList.add("is-open");
    widget.setAttribute("aria-hidden", "false");
    toggleBtn.classList.add("is-open");
    badge.classList.remove("show");
    messagesEl.scrollTop = messagesEl.scrollHeight;
    input.focus();
  }

  function closeChat() {
    isOpen = false;
    widget.classList.remove("is-open");
    widget.setAttribute("aria-hidden", "true");
    toggleBtn.classList.remove("is-open");
    if (isListening && recognition) { try { recognition.stop(); } catch (e) {} }
    resetVoiceUI();
  }

  function toggleChat() {
    if (isOpen) { closeChat(); } else { openChat(); }
  }

  toggleBtn.addEventListener("click", toggleChat);
  closeBtn.addEventListener("click", closeChat);

  /* ---- add message ---- */

  function addMessage(type, text) {
    var row = document.createElement("div");
    row.className = "msg-row " + type;

    if (type === "bot") {
      var avatar = document.createElement("img");
      avatar.className = "msg-avatar";
      avatar.src = "assets/chatbot-avatar.png";
      avatar.alt = "AI LILAMA2";
      avatar.addEventListener("error", function () {
        avatar.src = "data:image/jpeg;base64,";
        avatar.onerror = null;
      }, { once: true });
      row.appendChild(avatar);
    }

    var bubble = document.createElement("div");
    bubble.className = "msg-bubble";

    var para = document.createElement("p");
    para.style.margin = "0";
    para.textContent = text;
    bubble.appendChild(para);

    var time = document.createElement("div");
    time.className = "msg-time";
    var now = new Date();
    time.textContent = zeroPad(now.getHours()) + ":" + zeroPad(now.getMinutes());
    bubble.appendChild(time);

    row.appendChild(bubble);
    messagesEl.appendChild(row);
    messagesEl.scrollTop = messagesEl.scrollHeight;
  }

  function zeroPad(n) { return n < 10 ? "0" + n : "" + n; }

  /* ---- typing indicator ---- */

  function showTyping() { typingEl.classList.add("show"); }
  function hideTyping() { typingEl.classList.remove("show"); }

  /* ---- core ask ---- */

  function ask(text) {
    text = text.trim();
    if (!text) return;

    addMessage("user", text);
    showTyping();

    window.setTimeout(function () {
      getBotReply(text, function (reply) {
        hideTyping();
        addMessage("bot", reply);
      });
    }, 400);
  }

  function getBotReply(text, callback) {
    /* try server first */
    if (window.location.protocol === "http:" || window.location.protocol === "https:") {
      var xhr = new XMLHttpRequest();
      xhr.open("POST", "/api/chat", true);
      xhr.setRequestHeader("Content-Type", "application/json");
      xhr.setRequestHeader("X-Session-Id", chatSessionId);
      xhr.onreadystatechange = function () {
        if (xhr.readyState === 4) {
          if (xhr.status === 200) {
            try {
              var data = JSON.parse(xhr.responseText);
              if (data.context && typeof data.context === "object") {
                for (var k in data.context) {
                  if (data.context.hasOwnProperty(k)) chatContext[k] = data.context[k];
                }
              }
              callback(data.reply || "Dạ hiện em chưa có câu trả lời phù hợp ạ.");
              return;
            } catch (e) {}
          }
          /* fallback */
          fallbackReply(text, callback);
        }
      };
      xhr.timeout = 8000;
      xhr.ontimeout = function () { fallbackReply(text, callback); };
      xhr.onerror = function () { fallbackReply(text, callback); };
      xhr.send(JSON.stringify({ message: text, sessionId: chatSessionId, context: chatContext }));
    } else {
      fallbackReply(text, callback);
    }
  }

  function fallbackReply(text, callback) {
    var reply = window.AdmissionsBot.answer(text, chatContext);
    window.AdmissionsBot.updateContext(chatContext, text);
    callback(reply);
  }

  /* ---- form submit ---- */

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var value = input.value.trim();
    if (!value) return;
    input.value = "";
    ask(value);
  });

  /* ---- quick actions ---- */

  var quickBtns = document.querySelectorAll("[data-message]");
  for (var i = 0; i < quickBtns.length; i++) {
    quickBtns[i].addEventListener("click", function () {
      if (!isOpen) openChat();
      ask(this.getAttribute("data-message"));
    });
  }

  /* ---- voice input ---- */

  function setupVoice() {
    if (!voiceBtn) return;

    if (!SpeechRecognition || !window.isSecureContext) {
      voiceBtn.title = "Mở bàn phím và dùng micro của điện thoại";
      voiceBtn.addEventListener("click", openNativeKeyboard);
      return;
    }

    recognition = new SpeechRecognition();
    recognition.lang = "vi-VN";
    recognition.interimResults = true;
    recognition.continuous = false;

    voiceBtn.addEventListener("click", function () {
      if (isListening) { try { recognition.stop(); } catch (e) {} return; }
      try { recognition.start(); } catch (e) { resetVoiceUI(); openNativeKeyboard(); }
    });

    recognition.addEventListener("start", function () {
      isListening = true;
      voiceBtn.classList.add("is-listening");
      input.placeholder = "Đang nghe, anh/chị nói câu hỏi...";
    });

    recognition.addEventListener("result", function (event) {
      var transcript = "";
      for (var i = 0; i < event.results.length; i++) {
        transcript += event.results[i][0].transcript;
      }
      if (transcript.trim()) { input.value = transcript.trim(); }
    });

    recognition.addEventListener("error", function (event) {
      resetVoiceUI();
      if (["not-allowed", "service-not-allowed", "audio-capture", "network"].indexOf(event.error) !== -1) {
        openNativeKeyboard();
        return;
      }
      addMessage("bot", "Dạ hiện trình duyệt chưa ghi nhận được giọng nói. Anh/chị thử bấm micro lại hoặc nhập câu hỏi bằng bàn phím giúp em nhé.");
    });

    recognition.addEventListener("end", function () { resetVoiceUI(); input.focus(); });
  }

  function openNativeKeyboard() {
    input.focus();
    input.placeholder = "Bấm micro trên bàn phím điện thoại để nói...";
    if (hasShownVoiceFallback) return;
    hasShownVoiceFallback = true;
    addMessage("bot", "Dạ nếu điện thoại không ghi âm trực tiếp trong web, anh/chị bấm vào ô nhập rồi chọn biểu tượng micro trên bàn phím điện thoại để đọc câu hỏi giúp em nhé.");
  }

  function resetVoiceUI() {
    isListening = false;
    if (!voiceBtn) return;
    voiceBtn.classList.remove("is-listening");
    input.placeholder = "Nhập câu hỏi của anh/chị...";
  }

  setupVoice();

  /* ---- greeting on first open ---- */

  var greeted = false;

  function showGreeting() {
    if (greeted) return;
    greeted = true;
    window.setTimeout(function () {
      addMessage("bot", "Em chào anh/chị ạ. Em là trợ lý tư vấn tuyển sinh của trường, em có thể giúp gì cho anh chị?");
    }, 600);
  }

  /* override openChat to show greeting */
  var _origOpen = openChat;
  openChat = function () {
    _origOpen();
    showGreeting();
  };

  /* also show greeting if someone clicks a quick action before opening */
  for (var j = 0; j < quickBtns.length; j++) {
    (function (btn) {
      var _origClick = btn._listeners && btn._listeners.click;
      btn.addEventListener("click", function () {
        if (!isOpen) { openChat(); }
      });
    })(quickBtns[j]);
  }

  /* ---- expose for debugging ---- */
  window.__chatbot = {
    ask: ask,
    open: openChat,
    close: closeChat,
    context: chatContext
  };

})();

{
  "name": "lilama2-chatbot",
  "version": "2.0.0",
  "description": "AI Tư vấn tuyển sinh LILAMA2 - Floating Chat Widget",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^4.18.2"
  }
}

var express = require("express");
var path = require("path");
var app = express();
var PORT = process.env.PORT || 3000;

app.use(express.static(path.join(__dirname)));

app.get("/api/chat", function (req, res) {
  res.json({ reply: "Server API đang được nâng cấp. Vui lòng thử lại sau.", context: {} });
});

app.post("/api/chat", function (req, res) {
  res.json({ reply: "Server API đang được nâng cấp. Vui lòng thử lại sau.", context: {} });
});

app.listen(PORT, function () {
  console.log("LILAMA2 Chatbot running on port " + PORT);
});

var puppeteer = require("puppeteer");
var path = require("path");

(async function () {
  var browser = await puppeteer.launch({ headless: "new", args: ["--no-sandbox"] });
  var page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });
  await page.goto("http://localhost:3000", { waitUntil: "networkidle0" });
  await page.waitForTimeout(2000);
  await page.screenshot({ path: path.join(__dirname, "screenshot.png"), fullPage: false });
  console.log("Screenshot saved!");
  await browser.close();
})();
